import json
import hashlib

def config_digest(config):
    c=dict(config)
    if c.get('optional_probe') is None:
        c.pop('optional_probe',None)
    raw=json.dumps(c,sort_keys=True,separators=(',',':')).encode('utf-8')
    return hashlib.sha256(raw).hexdigest()

